class Solution:
    def minimumCost(self, nums: List[int]) -> int:
        n = len(nums)
        if n == 1:
            return nums[0]
        if n == 2:
            return max(nums)
        dp = [0] * n
        dp[n-1] = nums[n-1]
        dp[n-2] = max(nums[n-2], nums[n-1])
        for i in range(n - 3, -1, -1):
            a, b, c = nums[i], nums[i+1], nums[i+2]
            nxt = dp[i+2]
            dp[i] = min(max(a, b) + nxt, max(a, c) + nxt, max(b, c) + nxt)
        return dp[0]

