class Solution {
public:
    int minimumCost(vector<int>& nums) {
        int n = nums.size();
        if (n == 1) return nums[0];
        if (n == 2) return max(nums[0], nums[1]);
        vector<int> dp(n);
        dp[n-1] = nums[n-1];
        dp[n-2] = max(nums[n-2], nums[n-1]);
        for (int i = n - 3; i >= 0; i--) {
            int nxt = dp[i+2];
            dp[i] = min({max(nums[i], nums[i+1]) + nxt,
                         max(nums[i], nums[i+2]) + nxt,
                         max(nums[i+1], nums[i+2]) + nxt});
        }
        return dp[0];
    }
};

