class Solution {
    public int minimumCost(int[] nums) {
        int n = nums.length;
        if (n == 1) return nums[0];
        if (n == 2) return Math.max(nums[0], nums[1]);
        int[] dp = new int[n];
        dp[n-1] = nums[n-1];
        dp[n-2] = Math.max(nums[n-2], nums[n-1]);
        for (int i = n - 3; i >= 0; i--) {
            int nxt = dp[i+2];
            dp[i] = Math.min(Math.min(Math.max(nums[i], nums[i+1]), Math.max(nums[i], nums[i+2])) + nxt,
                             Math.max(nums[i+1], nums[i+2]) + nxt);
        }
        return dp[0];
    }
}

